CREATE TABLE athletes (id UUID PRIMARY KEY, name VARCHAR(60) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, bodyweight DOUBLE PRECISION NOT NULL CHECK(bodyweight BETWEEN 30 AND 300), standard VARCHAR(6) NOT NULL CHECK(standard IN ('male','female')));
CREATE TABLE sessions (token_hash VARCHAR(64) PRIMARY KEY, user_id UUID NOT NULL REFERENCES athletes(id) ON DELETE CASCADE, expires_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE lifts (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES athletes(id) ON DELETE CASCADE, exercise VARCHAR(60) NOT NULL, weight DOUBLE PRECISION NOT NULL CHECK(weight BETWEEN 0 AND 1500), reps INT NOT NULL CHECK(reps BETWEEN 1 AND 12), bodyweight DOUBLE PRECISION NOT NULL, standard VARCHAR(6) NOT NULL, score DOUBLE PRECISION NOT NULL, performed_on DATE NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX lifts_user ON lifts(user_id, performed_on DESC);
